const items = $input.all();
const blacklistDomains= ["technologycounter.com"];

/**
 * Normalize URL for deduplication
 * Supports: http://, https://, ftp://, ftps://, and any valid protocol
 * Removes: ports (:80, :443, :8080, etc.), www., query params, fragments, trailing slashes
 * Handles: IP addresses and domain names
 */
function normalizeUrl(urlString) {
  if (!urlString || typeof urlString !== 'string') {
    return null;
  }

  let url = urlString.trim().toLowerCase();

  // Remove any protocol (http://, https://, ftp://, ftps://, etc.)
  // Matches: protocol:// or protocol:/// (with optional slashes)
  url = url.replace(/^[a-z][a-z0-9+.-]*:\/\/\/*/i, '');

  // Remove www. prefix
  url = url.replace(/^www\./, '');

  // Extract host/domain part (before first /)
  const hostPart = url.split('/')[0];

  // Remove port number (e.g., :80, :443, :8080, :3000)
  // Matches : followed by digits at the end of host part
  let host = hostPart.replace(/:\d+$/, '');

  // Remove query params and fragment from path part
  const pathPart = url.includes('/') ? url.substring(url.indexOf('/')) : '';
  let path = pathPart.split('?')[0].split('#')[0];

  // Remove trailing slash from path
  if (path.endsWith('/')) {
    path = path.slice(0, -1);
  }

  // Combine host and path
  const normalized = path ? `${host}${path}` : host;

  return normalized || null;
}

function domainIsBlacklisted(key){
for (const blacklistDomain of blacklistDomains) {
  if(key.startsWith(blacklistDomain)){
    return true;
  }
}
  return false;
}

const seenUrl = new Map();
const seenId = new Map();
const results = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const url = item.json?.response?.url || item.json?.url;

  if (!url) {
    continue;
  }

  const normalizedKey = normalizeUrl(url);
  if(domainIsBlacklisted(normalizedKey)){
    continue;
  }
  if (!seenUrl.has(normalizedKey) && !seenId.has(item.json?.response?.id)) {
    seenUrl.set(normalizedKey, i);
    seenId.set(item.json.response.id, i);

    results.push({
      json: {
        ...item.json,
        _originalIndex: i,
        _normalizedUrl: normalizedKey
      }
    });
  }
}

return results.slice(0, 20);

