// Calculate qualityScore, apply diversity bonus, and select top 10 results
// Max 3 results per domain in final selection
// Output format optimized for Workflow_Execute_UpdateScoring

const inputItems = $input.all().map(item => item.json);

// Get original data from previous node (Code_SearchResult_NormalizeDeduplicateURL)
let originalResults = [];
try {
  const previousNodeData = $('Code_SearchResult_NormalizeDeduplicateURL').all();
  originalResults = previousNodeData.map(item => item.json);
} catch (e) {
  console.log('Could not access previous node data:', e);
}

// Helper function to extract domain from URL
// Supports: all protocols (http://, https://, ftp://, ftps://, etc.)
// Removes: ports (:80, :443, :8080, etc.), www. prefix
// Handles: IP addresses and domain names
function extractDomain(url) {
  if (!url || typeof url !== 'string') {
    return null;
  }

  let domain = url.trim().toLowerCase();

  // Remove any protocol (http://, https://, ftp://, ftps://, etc.)
  // Matches: protocol:// or protocol:/// (with optional slashes)
  domain = domain.replace(/^[a-z][a-z0-9+.-]*:\/\/\/*/i, '');

  // Remove www. prefix
  domain = domain.replace(/^www\./, '');

  // Extract host/domain part (before first /, ?, or #)
  domain = domain.split('/')[0].split('?')[0].split('#')[0];

  // Remove port number (e.g., :80, :443, :8080, :3000)
  // Matches : followed by digits at the end
  domain = domain.replace(/:\d+$/, '');
  domain = domain.trim();

  return domain || null;
}

// Create URL map from original results
const urlMap = {};
for (const original of originalResults) {
  const searchResultId = original.output?.searchResultId || 
                         original.response?.id || 
                         original.searchResultId;
  const url = original.response?.url || original.url || original.searchResult?.url;

  if (searchResultId && url) {
    urlMap[searchResultId] = url;
  }
}

// Extract and map scored results
const scoredResults = inputItems.map((item, index) => {
  const output = item.output || {};
  const searchResultId = output.searchResultId;
  const relevanceScore = output.relevanceScore || 0;
  const url = urlMap[searchResultId];

  if (!searchResultId) {
    console.log(`[Item ${index}] Missing searchResultId`);
    return null;
  }

  if (!url) {
    console.log(`[Item ${index}] Missing URL for searchResultId: ${searchResultId}`);
    return null;
  }

  return {
    searchResultId: searchResultId,
    relevanceScore: relevanceScore,
    url: url,
    originalData: item
  };
}).filter(r => r !== null && r.searchResultId && r.url);

// Group by domain for diversity bonus calculation
const domains = {};
for (const result of scoredResults) {
  const domain = extractDomain(result.url);

  if (!domain) continue;

  if (!domains[domain]) {
    domains[domain] = [];
  }
  domains[domain].push(result);
}

// Calculate qualityScore with diversity penalty
const allResults = [];
for (const domain in domains) {
  domains[domain].sort((a, b) => (b.relevanceScore || 0) - (a.relevanceScore || 0));

  for (let i = 0; i < domains[domain].length; i++) {
    const item = { ...domains[domain][i] };
    let qualityScore = item.relevanceScore || 0;

    if (i > 0) {
      qualityScore = Math.max(0, qualityScore - (i * 10));
    }

    item.qualityScore = qualityScore;
    allResults.push(item);
  }
}

// Sort by qualityScore (descending)
allResults.sort((a, b) => {
  const scoreA = a.qualityScore || 0;
  const scoreB = b.qualityScore || 0;

  if (scoreA === scoreB) {
    const relA = a.relevanceScore || 0;
    const relB = b.relevanceScore || 0;
    return relB - relA;
  }

  return scoreB - scoreA;
});

// Select top 10 with max 3 results per domain
const selected = [];
const domainCount = {};
let rank = 1;

for (const item of allResults) {
  if (selected.length >= 10) break;

  const domain = extractDomain(item.url);

  if (domain && domainCount[domain] >= 3) {
    continue;
  }

  selected.push({
    ...item,
    isSelected: true,
    selectionRank: rank++
  });

  if (domain) {
    domainCount[domain] = (domainCount[domain] || 0) + 1;
  }
}

// Build not selected items
const notSelected = [];
for (const item of allResults) {
  if (selected.some(s => s.searchResultId === item.searchResultId)) {
    continue;
  }

  notSelected.push({
    ...item,
    isSelected: false,
    selectionRank: null
  });
}

// Return ALL items individually (22 items)
const outputItems = [];

// Add selected items
for (const item of selected) {
  outputItems.push({ json: item });
}

// Add not selected items
for (const item of notSelected) {
  outputItems.push({ json: item });
}

return outputItems;

