// Group results by isSelected after UpdateScoring workflow
const inputItems = $input.all().map(item => item.json);

// Separate selected and notSelected
const selected = [];
const notSelected = [];

for (const item of inputItems) {
  // Extract data from response object if it exists
  const data = item.response || item;

  if (data.isSelected === true) {
    selected.push(data);
  } else {
    notSelected.push(data);
  }
}

// Sort selected by selectionRank
selected.sort((a, b) => (a.selectionRank || 0) - (b.selectionRank || 0));

// Return ONE item with grouped results
return [{
  json: {
    selected: selected,
    notSelected: notSelected,
    summary: {
      totalSelected: selected.length,
      totalNotSelected: notSelected.length,
      totalProcessed: inputItems.length
    }
  }
}];

